import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int nPoints = scanner.nextInt();
        if (nPoints <= 11) {
            long[][] pointsArray = new long[nPoints][5];
            for (int i = 0; i < nPoints; i++) {
                for (int j = 0; j < 5; j++) {
                    pointsArray[i][j] = scanner.nextLong();
                }
            }
            long[][][] vectorsArray = new long[nPoints][nPoints][5];
            for (int i = 0; i < nPoints; i++) {
                for (int j = 0; j < nPoints; j++) {
                    for (int k = 0; k < 5; k++) {
                        vectorsArray[i][j][k] = pointsArray[j][k] - pointsArray[i][k];
                    }
                }
            }
            java.util.HashSet<Integer> affectedIndices = new java.util.HashSet<>();
            for (int i = 0; i < nPoints; i++) {
                boolean affected = false;
                for (int j = 0; j < nPoints; j++) {
                    for (int k = 0; k < nPoints; k++) {
                        if (!vectorsEqual(vectorsArray[i][j], vectorsArray[i][k]) && vectorsDotProduct(vectorsArray[i][j], vectorsArray[i][k])) {
                            affectedIndices.add(i + 1);
                            affected = true;
                            break;
                        }
                    }
                    if (affected) break;
                }
            }
            System.out.println(nPoints - affectedIndices.size());
            for (int i = 1; i <= nPoints; i++) {
                if (!affectedIndices.contains(i))
                    System.out.println(i);
            }
        } else {
            System.out.println(0);
        }
    }

    private static boolean vectorsEqual(long[] a, long[] b) {
        for (int i = 0; i < 5; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    private static boolean vectorsDotProduct(long[] a, long[] b) {
        long sum = 0;
        for (int i = 0; i < 5; i++) {
            sum += a[i] * b[i];
        }
        return sum > 0;
    }
}
